using System.Text.Json.Serialization;
using GeminiAPIWrapper.Serialization;

namespace GeminiAPIWrapper.Configurations;

/// <summary>
/// Producer role of a <see cref="Content"/> message in a conversation.
/// See <see href="https://ai.google.dev/api/caching#Content"/>.
/// </summary>
[JsonConverter(typeof(LenientStringEnumConverter<Role>))]
public enum Role
{
    /// <summary>
    /// Content provided by the end user or tool caller (<c>user</c>).
    /// </summary>
    [JsonStringEnumMemberName("user")]
    User,

    /// <summary>
    /// Content generated by the model (<c>model</c>).
    /// </summary>
    [JsonStringEnumMemberName("model")]
    Model,
}
